import json

with open("/home/USER/runs/paper/qwen-hpl0-u1-turns/frozen/held-out-reference-3/play/users/u070/system/state/workspace/programs/task-a7a8b5fa.json", "r") as f:
    demos_raw = json.load(f)

print(f"Number of demos loaded: {len(demos_raw)}")
print(f"First demo keys: {list(demos_raw[0].keys())}")

demos = [
    {"input": demos_raw[0]["input"], "output": demos_raw[0]["output"]},
    {"input": demos_raw[1]["input"], "output": demos_raw[1]["output"]}
]

def get_pos(grid):
    pos = {}
    for r, row in enumerate(grid):
        for c, cell in enumerate(row):
            if cell == 1:
                pos["1"] = (r, c)
            elif cell == 2:
                pos["2"] = pos.get("2", (r,c))  # keep first found
    return pos

for i, demo in enumerate(demos):
    inp = demo["input"]
    out = demo["output"]

    print(f"\n=== Demo {i+1} ===")
    in_pos = get_pos(inp)
    out_pos = get_pos(out)
    threes = [(r,c) for r,row in enumerate(out) for c,cell in enumerate(row) if cell==3]
    three_sorted = sorted(threes)

    print(f"Demo {i+1}: 2 at {in_pos[2]}, 1 at {in_pos[1]}")
    print(f"Output 3s: {len(threes)} cells: {three_sorted}")

    print("Transitions between 3s:")
    for j in range(len(threes)):
        r, c = three_sorted[j]
        if j < len(threes) - 1:
            next_r, next_c = three_sorted[j+1]
            deltas = (next_r - r, next_c - c)
            arrow = "->" if deltas != (0,0) else ""
            print(f"  ({r},{c}) {arrow} ({next_r},{next_c}) (delta: {deltas})")
        else:
            print(f"  ({r},{c}) [last]")

